using namespace raster::common;
using namespace raster::filter;

namespace {

int failed = 0;

void check(bool cond, const char* test_name) {
    if (!cond) {
        std::println(stderr, "FAIL: {}", test_name);
        ++failed;
    } else {
        std::println("PASS: {}", test_name);
    }
}

void check_pixel(const Pixel& pixel, uint8_t er, uint8_t eg, uint8_t eb, const char* test_name) {
    if (pixel.r != er || pixel.g != eg || pixel.b != eb) {
        std::println(stderr, "FAIL: {} -- got ({},{},{}) expected ({},{},{})", test_name, pixel.r,
                     pixel.g, pixel.b, er, eg, eb);
        ++failed;
    } else {
        std::println("PASS: {}", test_name);
    }
}

// -------------------------------------------------------------------
// pixel_to_grayscale tests
// -------------------------------------------------------------------

void test_grayscale_black() {
    auto out = pixel_to_grayscale(Pixel{0, 0, 0});
    check_pixel(out, 0, 0, 0, "grayscale black");
}

void test_grayscale_white() {
    auto out = pixel_to_grayscale(Pixel{255, 255, 255});
    check_pixel(out, 255, 255, 255, "grayscale white");
}

void test_grayscale_red() {
    auto out = pixel_to_grayscale(Pixel{255, 0, 0});
    check_pixel(out, 76, 76, 76, "grayscale red -> 76");
}

void test_grayscale_green() {
    auto out = pixel_to_grayscale(Pixel{0, 255, 0});
    check_pixel(out, 150, 150, 150, "grayscale green -> 150");
}

void test_grayscale_mixed() {
    auto out = pixel_to_grayscale(Pixel{100, 150, 200});
    check_pixel(out, 141, 141, 141, "grayscale mixed -> 141");
}

// -------------------------------------------------------------------
// pixel_threshold tests
// -------------------------------------------------------------------

void test_threshold_above() {
    auto out = pixel_threshold(Pixel{255, 255, 255}, 100);
    check_pixel(out, 255, 255, 255, "threshold above (luma 255 > 100) -> white");
}

void test_threshold_below() {
    auto out = pixel_threshold(Pixel{0, 0, 0}, 100);
    check_pixel(out, 0, 0, 0, "threshold below (luma 0 < 100) -> black");
}

void test_threshold_exactly_at() {
    auto out_above = pixel_threshold(Pixel{77, 0, 0}, 23);
    check_pixel(out_above, 255, 255, 255, "threshold at boundary (above) -> white");
    auto out_below = pixel_threshold(Pixel{76, 0, 0}, 23);
    check_pixel(out_below, 0, 0, 0, "threshold at boundary (below) -> black");
}

void test_threshold_edge() {
    auto out = pixel_threshold(Pixel{0, 0, 0}, 0);
    check_pixel(out, 0, 0, 0, "threshold 0 with luma 0 -> black");
}

// -------------------------------------------------------------------
// image-level filter tests (pixels within images)
// -------------------------------------------------------------------

void check_image(const Image& img, std::span<const Pixel> expected, const char* label) {
    if (img.pixel_count() != expected.size()) {
        std::println(stderr, "FAIL: {} -- pixel count {} expected {}", label, img.pixel_count(),
                     expected.size());
        ++failed;
        return;
    }
    for (std::size_t i = 0; i < expected.size(); ++i) {
        const Pixel& got = img.pixels()[i];
        const Pixel& want = expected[i];
        if (got.r != want.r || got.g != want.g || got.b != want.b) {
            std::println(stderr, "FAIL: {} pixel {} -- got ({},{},{}) expected ({},{},{})", label,
                         i, got.r, got.g, got.b, want.r, want.g, want.b);
            ++failed;
        } else {
            std::println("PASS: {} pixel {}", label, i);
        }
    }
}

void test_grayscale_image_2x2() {
    auto input = std::istringstream("P3\n2 2\n255\n"
                                    "255 0 0 0 255 0\n"
                                    "0 0 255 30 31 66\n");
    auto result = Image::read(input);
    check(result.value.has_value(), "grayscale image 2x2: input readable");
    if (!result.value.has_value())
        return;
    auto& image = *result.value;
    apply_grayscale(image);
    const std::array<Pixel, 4> expected = {Pixel{76, 76, 76}, Pixel{150, 150, 150},
                                           Pixel{29, 29, 29}, Pixel{35, 35, 35}};
    check_image(image, expected, "grayscale image 2x2");
}

void test_threshold_image_2x2() {
    auto input = std::istringstream("P3\n2 2\n255\n"
                                    "255 0 0 0 255 0\n"
                                    "0 0 255 30 31 66\n");
    auto result = Image::read(input);
    check(result.value.has_value(), "threshold image 2x2: input readable");
    if (!result.value.has_value())
        return;
    auto& image = *result.value;
    apply_threshold(image, 100);
    const std::array<Pixel, 4> expected = {Pixel{0, 0, 0}, Pixel{255, 255, 255}, Pixel{0, 0, 0},
                                           Pixel{0, 0, 0}};
    check_image(image, expected, "threshold image 2x2");
}

void test_grayscale_image_3x3() {
    auto input = std::istringstream("P3\n3 3\n255\n"
                                    "30 31 45 30 31 66 128 128 128\n"
                                    "100 100 100 30 164 196 30 164 200\n"
                                    "10 20 30 200 100 50 50 200 100\n");
    auto result = Image::read(input);
    check(result.value.has_value(), "grayscale image 3x3: input readable");
    if (!result.value.has_value())
        return;
    auto& image = *result.value;
    apply_grayscale(image);
    const std::array<Pixel, 9> expected = {
        Pixel{32, 32, 32},    Pixel{35, 35, 35},    Pixel{128, 128, 128},
        Pixel{100, 100, 100}, Pixel{128, 128, 128}, Pixel{128, 128, 128},
        Pixel{18, 18, 18},    Pixel{124, 124, 124}, Pixel{144, 144, 144}};
    check_image(image, expected, "grayscale image 3x3");
}

void test_threshold_image_3x3() {
    auto input = std::istringstream("P3\n3 3\n255\n"
                                    "30 31 45 30 31 66 128 128 128\n"
                                    "100 100 100 30 164 196 30 164 200\n"
                                    "10 20 30 200 100 50 50 200 100\n");
    auto result = Image::read(input);
    check(result.value.has_value(), "threshold image 3x3: input readable");
    if (!result.value.has_value())
        return;
    auto& image = *result.value;
    apply_threshold(image, 100);
    const std::array<Pixel, 9> expected = {
        Pixel{0, 0, 0}, Pixel{0, 0, 0},       Pixel{255, 255, 255},
        Pixel{0, 0, 0}, Pixel{255, 255, 255}, Pixel{255, 255, 255},
        Pixel{0, 0, 0}, Pixel{255, 255, 255}, Pixel{255, 255, 255}};
    check_image(image, expected, "threshold image 3x3");
}

