input.oldString:
// -------------------------------------------------------------------
// image-level filter tests (pixels within images)
// -------------------------------------------------------------------

static void check_image_pixels(const struct Image* img, const uint8_t* rgb, int count,
                               const char* label) {
    for (int i = 0; i < count; ++i) {
        char name[128];
        snprintf(name, sizeof name, "%s: pixel %d", label, i);
        check_pixel(&img->pixels[i], rgb[3 * i], rgb[3 * i + 1], rgb[3 * i + 2], name);
    }
}

static void test_grayscale_image_2x2(void) {
    FILE* input = make_ppm("P3\n2 2\n255\n"
                           "255 0 0 0 255 0\n"
                           "0 0 255 30 31 66\n");
    struct PpmResult result = ppm_read(input);
    check(result.error == PRE_OK, "grayscale image 2x2: input readable");
    if (result.error == PRE_OK) {
        apply_grayscale(&result.image);
        const uint8_t expected[] = {76, 76, 76, 150, 150, 150, 29, 29, 29, 35, 35, 35};
        check_image_pixels(&result.image, expected, 4, "grayscale image 2x2");
        ppm_image_free(&result.image);
    }
    fclose(input);
}

static void test_threshold_image_2x2(void) {
    FILE* input = make_ppm("P3\n2 2\n255\n"
                           "255 0 0 0 255 0\n"
                           "0 0 255 30 31 66\n");
    struct PpmResult result = ppm_read(input);
    check(result.error == PRE_OK, "threshold image 2x2: input readable");
    if (result.error == PRE_OK) {
        apply_threshold(&result.image, 100);
        const uint8_t expected[] = {0, 0, 0, 255, 255, 255, 0, 0, 0, 0, 0, 0};
        check_image_pixels(&result.image, expected, 4, "threshold image 2x2");
        ppm_image_free(&result.image);
    }
    fclose(input);
}

static void test_grayscale_image_3x3(void) {
    FILE* input = make_ppm("P3\n3 3\n255\n"
                           "30 31 45 30 31 66 128 128 128\n"
                           "100 100 100 30 164 196 30 164 200\n"
                           "10 20 30 200 100 50 50 200 100\n");
    struct PpmResult result = ppm_read(input);
    check(result.error == PRE_OK, "grayscale image 3x3: input readable");
    if (result.error == PRE_OK) {
        apply_grayscale(&result.image);
        const uint8_t expected[] = {32,  32,  32,  35,  35,  35,  128, 128, 128,
                                    100, 100, 100, 128, 128, 128, 128, 128, 128,
                                    18,  18,  18,  124, 124, 124, 144, 144, 144};
        check_image_pixels(&result.image, expected, 9, "grayscale image 3x3");
        ppm_image_free(&result.image);
    }
    fclose(input);
}

static void test_threshold_image_3x3(void) {
    FILE* input = make_ppm("P3\n3 3\n255\n"
                           "30 31 45 30 31 66 128 128 128\n"
                           "100 100 100 30 164 196 30 164 200\n"
                           "10 20 30 200 100 50 50 200 100\n");
    struct PpmResult result = ppm_read(input);
    check(result.error == PRE_OK, "threshold image 3x3: input readable");
    if (result.error == PRE_OK) {
        apply_threshold(&result.image, 100);
        const uint8_t expected[] = {0, 0, 0, 0,   0,   0,   255, 255, 255,
                                    0, 0, 0, 255, 255, 255, 255, 255, 255,
                                    0, 0, 0, 255, 255, 255, 255, 255, 255};
        check_image_pixels(&result.image, expected, 9, "threshold image 3x3");
        ppm_image_free(&result.image);
    }
    fclose(input);
}

