```cpp
// Fails once `limit` bytes have been accepted; sets errno to `err`.
class FailAfterBuf : public std::streambuf {
  public:
    FailAfterBuf(std::size_t limit, int err) : limit_(limit), err_(err) {}
  protected:
    int_type overflow(int_type c) override {
        if (c == traits_type::eof())
            return traits_type::not_eof(c);
        if (count_ >= limit_) {
            errno = err_;
            return traits_type::eof();
        }
        ++count_;
        return traits_type::not_eof(c);
    }
  private:
    std::size_t limit_;
    int err_;
    std::size_t count_ = 0;
};
```

