void test_writer_stream_error() {
    auto ss = std::ostringstream();
    ss.setstate(std::ios::badbit);
    PpmWriter pw(ss, 2, 2);
    auto r = pw.putHeader();
    check(!r.value.has_value(), "bad stream header -> error");
