enum TokenResult {
    TOKEN_OK,
    TOKEN_EOF,
    TOKEN_ERROR,
};

// Helper: read a full integer token, skipping whitespace/comments.
// allow_hash: 1 = header (skip #-lines), 0 = return '#' to caller
// On TOKEN_OK, *val is set (may be negative). On TOKEN_ERROR, result->diagnostic is set.
// On TOKEN_EOF, nothing is set; the caller chooses the diagnostic.
static enum TokenResult read_int_token(FILE* f, int* line_num, int allow_hash, long long* val,
                                       struct PpmResult* result) {
    int c = skip_field(f, line_num, allow_hash);
    if (c == EOF) {
        if (ferror(f)) {
            int e = errno;
            char buf[256];
            safe_strerror(e, buf, sizeof buf);
            result->error = PRE_IO_ERROR;
            result->error_line = *line_num;
            snprintf(result->diagnostic, sizeof(result->diagnostic), "сбой чтения: %s (errno %d)",
                     buf, e);
            return TOKEN_ERROR;
        }
        return TOKEN_EOF;
    }

    if (c == '#') {
        result->error = PRE_BAD_NUMBER;
        result->error_line = *line_num;
        snprintf(result->diagnostic, sizeof(result->diagnostic),
                 "строка %d: символ '#' не допускается в данных", *line_num);
        return TOKEN_ERROR;
    }

    // Collect the full token (until whitespace / '#' / EOF), keeping a bounded copy for diagnostics.
    char token[128];
    size_t token_len = 0;
    int has_dot = 0;
    int has_plus = 0;
    int has_digit = 0;
    int has_minus = 0;
    int token_truncated = 0;
    long long v = 0;
    int overflow = 0;

    for (;;) {
        if (c == EOF)
            break;
        if (c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '#')
            break;

        if (token_len + 1 < sizeof(token)) {
            token[token_len] = (char)c;
        } else {
            token_truncated = 1;
        }
        ++token_len;

        if (c == '.')
            has_dot = 1;
        else if (c == '+')
            has_plus = 1;
        else if (c == '-')
            has_minus = 1;
        else if (c >= '0' && c <= '9') {
            has_digit = 1;
            if (!overflow) {
                v = v * 10 + (c - '0');
                if (v > 0x7FFFFFFF)
                    overflow = 1;
            }
        }

        c = fgetc(f);
    }
    if (c != EOF)
        ungetc(c, f);

    // token string for messages (truncated if needed)
