New `read_passport.c`:
```c
#include "read_passport.h"

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "../../common/c/strerror.h"

struct PassportResult read_passport(FILE* in) {
    printf("Введите название изображения: \n");

    char name_buf[1024];
    if (!fgets(name_buf, sizeof(name_buf), in)) {
        if (feof(in))
            return (struct PassportResult){.error = PE_NO_INPUT};
        return (struct PassportResult){.error = PE_IO_ERROR, .system_errno = errno};
    }

    size_t name_len = strlen(name_buf);
    if (name_len > 0 && name_buf[name_len - 1] == '\n')
        name_buf[--name_len] = '\0';

    while (name_len > 0 && (name_buf[name_len - 1] == ' ' || name_buf[name_len - 1] == '\t'))
        name_buf[--name_len] = '\0';
    size_t trim_start = 0;
    while (name_buf[trim_start] == ' ' || name_buf[trim_start] == '\t')
        trim_start++;
    if (trim_start > 0) {
        name_len -= trim_start;
        memmove(name_buf, name_buf + trim_start, name_len + 1);
    }

    if (name_len == 0)
        return (struct PassportResult){.error = PE_EMPTY_NAME};

    char* name = (char*)malloc(name_len + 1);
    if (!name)
        return (struct PassportResult){.error = PE_IO_ERROR, .system_errno = errno};
    memcpy(name, name_buf, name_len + 1);

    printf("Введите количество пикселей: \n");

    char count_str[64];
    if (!fgets(count_str, sizeof(count_str), in)) {
        free(name);
        if (feof(in))
            return (struct PassportResult){.error = PE_NO_INPUT};
        return (struct PassportResult){.error = PE_IO_ERROR, .system_errno = errno};
    }

    size_t count_len = strlen(count_str);
    if (count_len > 0 && count_str[count_len - 1] == '\n')
        count_str[--count_len] = '\0';

    char* end = NULL;
    errno = 0;
    long count = strtol(count_str, &end, 10);
    if (end == count_str || *end != '\0' || errno == ERANGE) {
        struct PassportResult r = {.error = PE_BAD_COUNT};
        snprintf(r.bad_value, sizeof r.bad_value, "%s", count_str);
        free(name);
        return r;
    }
    if (count <= 0) {
        struct PassportResult r = {.error = PE_NEGATIVE_COUNT};
        snprintf(r.bad_value, sizeof r.bad_value, "%s", count_str);
        free(name);
        return r;
    }

    struct PassportResult r = {.error = PE_OK, .name = name, .count = (int32_t)count};
    return r;
}

void passport_error_message(const struct PassportResult* result, char* buf, size_t bufsz) {
    switch (result->error) {
    case PE_NO_INPUT:
        snprintf(buf, bufsz, "Нет ввода");
        break;
    case PE_EMPTY_NAME:
        snprintf(buf, bufsz, "Название изображения не может быть пустым");
        break;
    case PE_BAD_COUNT:
        snprintf(buf, bufsz, "количество пикселей должно быть числом; получено: %s",
                 result->bad_value);
        break;
    case PE_NEGATIVE_COUNT:
        snprintf(buf, bufsz, "количество пикселей должно быть положительным; получено: %s",
                 result->bad_value);
        break;
    case PE_IO_ERROR: {
        char errbuf[256];
        safe_strerror(result->system_errno, errbuf, sizeof errbuf);
        snprintf(buf, bufsz, "Сбой ввода: %s (errno %d)", errbuf, result->system_errno);
        break;
    }
    default:
        buf[0] = '\0';
        break;
    }
}
```

Wait, there's a subtlety with `count_str[64]`: if the input line is longer than 63 chars, `fgets` reads 63 chars + '\0', leaving the rest in the stream. The `*end != '\0'` check would catch non-numeric, but for a long numeric string, `strtol` might parse the first 63 digits and `*end == '\0'` → treated as valid (wrong). Edge case; pre-existing behavior. Not in scope. Actually, the original had the same. Leave.

Also, `strtol` overflow: `errno == ERANGE` check. The original had separate checks for `end == count_str || *end != '\0'` and `errno == ERANGE`. I combined with `||`. Fine.

Hmm, but careful: I set `errno = 0` before `strtol`, then check `errno == ERANGE` after. But the combined `if (end == count_str || *end != '\0' || errno == ERANGE)`. Good.

Now, the malloc path: `system_errno = errno`. But `malloc` failure sets `errno = ENOMEM` (POSIX; MSVC sets ENOMEM too). OK.

Now, the `PE_IO_ERROR` for the first `fgets`: `system_errno = errno`. On a write-only stream, `fgets` sets errno = EBADF (MSVC). Good.

